import errno
import os
import time
from concurrent.futures import ThreadPoolExecutor
from logging import Logger
from shutil import Error, make_archive, move
from threading import Event, Lock

from six import with_metaclass

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import DEF_ALL_PLUGS_START_TIMEOUT, DEF_ALL_PLUGS_STOP_TIMEOUT, LOGGER_PORT, SERVER_HOST
from ta_logcollector.utils.common import move_logs_to_specified_directory, Singleton
from ta_logcollector.utils.internal import create_dir, get_current_datetime

logger = Logger("LC")


def run_collector(name, stop_event, collecting_started, collector, started_callback, stopped_callback):
    """
    Main function to execute collector for plugin.

    :param name: plugin name
    :param stop_event: event notification for stoping collection
    :param collecting_started: event notification when collection started
    :param collector: plugin function/object
    :param started_callback: callback function when plugin started
    :param stopped_callback: callback function when plugin stopped
    """
    logger.info("Run Collector: {}".format(name))
    with collector:
        collecting_started.set()
        started_callback(name)
        stop_event.wait()
    stopped_callback(name)


def start_callback(collector_name):
    """
    General callback fired when plugin start collecting.

    :param collector_name: plugin name
    """
    logger.info("started {}".format(collector_name))


def stop_callback(collector_name):
    """
    General callback fired when plugin stop collecting.

    :param collector_name: plugin name
    """
    logger.info("stopped {}".format(collector_name))


def _await_all_started(plugins, timeout=300.0):
    # type: (list, float) -> None
    """
    Wait until all scheduled plugins started or timed-out.
    :param plugins: list of plugins as dict with complete info
    :param timeout: default 300.0
    :return: None
    """
    start_time = time.time()
    while time.time() - start_time < timeout:
        if not plugins:
            logger.warning("No plugins left to wait for start")
            break
        for plugin in plugins:
            if plugin["future"].done():
                _log_error_on_future_start(
                    plugin["name"], reason="plugin error upon startup - check DEBUG logs for details from plugin."
                )
                plugins.remove(plugin)
                break
        if not [0 for plugin in plugins if not plugin["collect_started"].is_set()] and plugins:
            logger.info("{0} all events set {0}".format(10 * "*"))
            break
    else:
        for plugin in plugins:
            if not plugin["collect_started"].is_set():
                _log_error_on_future_start(plugin["name"], reason="timeout")


def _log_error_on_future_start(plugin_name, reason):
    # type: (str, str) -> None
    """
    Stops all plugins if error on startup occurred. It is done by setting global "stop_env" and allowing all
    context managers to finish
    :param plugin_name: name of plugin
    :param reason: reason why future stopped upon plugin start action
    :return: None
    """
    logger.error("Plugin [{}] startup procedure failed with reason: {}".format(plugin_name, reason))


def _prepare_plugins_details(provided_plugins, log_dir):
    # type: (Union[Callable, List[Callable]], str) -> List[Dict[str, Any]]
    """
    Get details of plugins

    :param provided_plugins:
    :param log_dir:
    :return:
    """
    provided_plugins = [provided_plugins] if not isinstance(provided_plugins, list) else provided_plugins
    return [
        {
            "name": plugin.name,
            "args": plugin.args,
            "kwargs": plugin.kwargs,
            "log_dir": log_dir,
            "plugin": plugin(log_dir=log_dir),
            "collect_started": Event(),
            "stop_evt": Event(),
        }
        for plugin in provided_plugins
    ]


class Runner(with_metaclass(Singleton)):
    """Runner is handling execution of plugins."""

    def __init__(self, log_host, log_port=LOGGER_PORT):
        # type: (str, int) -> None
        """
        Simple initialization of Runner.

        :param log_host: IP address of logger host
        :param log_port: port of logger host
        """
        self.plugins = []  # type: List[Dict[str, Any]]
        self.root_log_dir = ""
        self.current_log_dir_name = ""
        self._plugins_stop_ongoing = []  # type: List[Dict[str, Any]]
        self._ongoing_stop_lock = Lock()
        global logger
        logger = get_net_logger(log_host, log_port, name="{}_{}".format(self.__class__.__name__, SERVER_HOST))

    def __del__(self):
        """Clear Runner instance after explicit call of __dell__ func. This should be done only in UT."""
        Runner._instances = {}

    def start(self, activated_plugins, log_dir):
        # type: (List[Callable], str) -> None
        """
        Schedule all plugins to start collecting logs.

        :param activated_plugins: list of plugins instances
        :param log_dir: path to root logs directory
        """
        logger.debug("Runner started ")
        th_pool = ThreadPoolExecutor(max_workers=20)
        create_dir(log_dir)
        requested_plugins = _prepare_plugins_details(activated_plugins, log_dir)
        logger.debug("Plugins to be activated = {}".format([plugin["name"] for plugin in requested_plugins]))

        for plugin in requested_plugins:
            collector_future = th_pool.submit(
                run_collector,
                plugin["name"],
                plugin["stop_evt"],
                plugin["collect_started"],
                plugin["plugin"],
                start_callback,
                stop_callback,
            )
            logger.debug("Thread for plugin {} created".format(plugin["name"]))
            plugin["future"] = collector_future
        _await_all_started(requested_plugins, timeout=DEF_ALL_PLUGS_START_TIMEOUT)
        self._add_requested_plugins_to_activated_plugins(requested_plugins)

    def stop(self, plugins_list=None):
        # type: (Optional[list]) -> None
        """
        Trigger all plugins to stop collecting logs.
        :param plugins_list: list of plugins to be stopped or None if all plugins should be stopped
        """
        plugins = self._get_plugins_to_stop(plugins_list)
        self._validate_plugins_to_stop(plugins)
        self._set_stop_evt_for_plugins(plugins)
        self._get_results_from_plugins(plugins)

    def _add_requested_plugins_to_activated_plugins(self, requested_plugins):
        self.plugins.extend(requested_plugins)

    def _get_results_from_plugins(self, plugins_list):
        # type: (List[Dict[str, Any]]) -> None
        debug_start_time = plug_start_timer = time.time()
        while plugins_list and (time.time() - plug_start_timer) <= 4 * DEF_ALL_PLUGS_STOP_TIMEOUT:
            for plugin in plugins_list:
                if plugin["future"].done():
                    try:
                        logger.info(
                            "Plugin '{}' finished and returned '{}'".format(plugin["name"], plugin["future"].result())
                        )
                    except Exception as exc:
                        logger.exception(
                            "Unhandled error occurred during execution of [{}: args: {}]: {}:{}".format(
                                plugin["name"], plugin["args"], type(exc).__name__, exc
                            ),
                            exc_info=True,
                        )
                    finally:
                        plugins_list.remove(plugin)
                        if self.plugins is not plugins_list:
                            self.plugins.remove(plugin)
                        break
            now = time.time()
            if now - debug_start_time >= 60:
                debug_start_time = now
                logger.debug("Waiting for result from plugins: {}".format([plugin["name"] for plugin in plugins_list]))
            time.sleep(0.5)
        if plugins_list:
            logger.error(
                "Plugins ({}) did not stop within {}s timeout! Please restart lc_server before next start.".format(
                    [plugin["name"] for plugin in plugins_list], 4 * DEF_ALL_PLUGS_STOP_TIMEOUT
                )
            )

    def _clear_plugins_list(self, plugins):
        # type: (list) -> None
        for plugin in list(plugins):
            self.plugins.remove(plugin)

    @staticmethod
    def _set_stop_evt_for_plugins(plugins):
        # type: (List[Dict[str, Any]]) -> None
        for plugin in plugins:
            plugin["stop_evt"].set()

    def _validate_plugins_to_stop(self, plugins):
        # type: (List[Dict[str, Any]]) -> None
        with self._ongoing_stop_lock:
            for plugin in plugins[:]:
                if plugin in self._plugins_stop_ongoing:
                    plugins.remove(plugin)
            self._plugins_stop_ongoing.extend(plugins)

    def _get_plugins_to_stop(self, plugins_list):
        # type: (Optional[list]) -> List[Dict[str, Any]]
        if not plugins_list:
            return self.plugins
        plugins = []
        for plugin in self.plugins:
            plugin_name = plugin["name"]
            if plugin_name in plugins_list:
                plugins.append(plugin)
                plugins_list.remove(plugin_name)
        for plugin_name in plugins_list:
            logger.warning("Plugin {} not found in started plugins list!".format(plugin_name))
        return plugins


def get_root_and_base_log_dir(log_dir):
    # type: (str) -> List[str]
    """Splits path to root path and last directory"""
    log_dir = log_dir if not log_dir.endswith("/") else log_dir[:-1]
    return os.path.split(log_dir)


def compress_and_move_archive(compression_type, directory_path):
    # type: (str, str) -> str
    """
    Compresses and moves archive to the root directory with logs
    :param compression_type: name of chosen compression
    :param directory_path: name of directory with current logs
    :return: final location of archived logs
    """
    root_log_dir, current_log_dir_name = get_root_and_base_log_dir(directory_path)
    _move_logs_collected_during_suite_setup(directory_path)
    if (
        not compression_type
        or compression_type is None
        or compression_type is False
        or str(compression_type).lower() == "none"
    ):
        return str(os.path.join(root_log_dir, current_log_dir_name))
    _remove_old_compressed_file(root_log_dir)

    archive_location = compress(
        arch_name=os.path.join(root_log_dir, "_".join([SERVER_HOST, get_current_datetime()])),
        root_directory=os.path.join(root_log_dir, current_log_dir_name),
        compression=compression_type,
    )
    final_archive_location = _move_archive_to_final_location(archive_location, root_log_dir)
    logger.debug("Archive location = %s", final_archive_location)
    return final_archive_location


def _move_logs_collected_during_suite_setup(dir_path):
    # type: (str) -> None
    """
    Move log files collected during suite setup, but stopped during teardown.
    Dirty hack for issue: #154 and !112
    :param dir_path: full path to directory
    """
    suite_teardown = [dir_name for dir_name in os.listdir(dir_path) if "Suite Teardown" in dir_name]
    logger.debug("Teardown: {}".format(suite_teardown))
    if suite_teardown:
        dist_dir = os.path.join(dir_path, suite_teardown[0])
        src_dir = os.path.join(dir_path, "00 Suite Setup")
        regexp_files = ["snapshot", "egate_console", "SosReport"]
        src_dir_list = list(os.listdir(src_dir))
        logger.debug("Source directory list: {}".format(src_dir_list))
        for file_regex in [
            "{}*".format(reg_ex) for src_file in src_dir_list for reg_ex in regexp_files if reg_ex in src_file
        ]:
            move_logs_to_specified_directory(logger, dst_path=dist_dir, src_path=src_dir, regex=file_regex)


def _move_archive_to_final_location(archive_location, root_log_dir):
    # type: (str, str) -> str
    """
    Moves archive to final location and returns archive name with full path
    :param archive_location: src archive location
    :param root_log_dir: dst archive location
    :return: archive location with full path
    """
    archive_name = os.path.split(archive_location)[-1]
    try:
        move(src=archive_location, dst=os.path.join(root_log_dir))
    except Error:
        logger.debug("lc_server launched from logs directory. Cannot move archive as it's already in place")
    final_archive_location = os.path.join(root_log_dir, archive_name)
    logger.debug("final_archive_location = {}".format(final_archive_location))
    return final_archive_location


def _remove_old_compressed_file(root_log_dir):
    # type: (str) -> None
    """
    Tries to remove old compressed file
    :param root_log_dir: path to root directory where new file can be stored
    """
    try:
        os.remove(os.path.join(root_log_dir, SERVER_HOST))
    except OSError:
        pass


def prepare_logs_directory(root_log_dir, base_dir):
    # type: (str, str) -> str
    """
    Creates a new directory for logs with current date and time and self IP address
    :param root_log_dir: path to root logs directory
    :param base_dir: base directory name for logs
    :return: path to newly created directory where logs should be stored
    """
    new_logs_dir_name = "{}_{}".format(base_dir, SERVER_HOST)
    full_logs_path = os.path.join(root_log_dir, new_logs_dir_name)
    try:
        os.makedirs(full_logs_path)
    except OSError as exc:
        if exc.errno != errno.EEXIST:
            logger.error(type(exc).__name__, exc)
            raise  # full path exists, but shouldn't. Can it happen?
    return new_logs_dir_name


def compress(arch_name, root_directory, compression):
    # type: (str, str, str) -> str
    """
    Compress directory with compression type as arch_name.
    When compression is unknown function returns empty string.

    :param arch_name: name of archive without extension
    :param root_directory: root directory to compress
    :param compression: allow values: zip, gztar, bztar, xztar (only for Python 3.3+)
    :return: the full path of the archive file
    """
    name = ""
    try:
        name = make_archive(base_name=arch_name, format=compression, root_dir=root_directory)
    except ValueError as err:
        logger.debug("Compression error: {}".format(str(err)), exc_info=True)
    logger.debug("Make archive: {}".format(name))
    return name
